package org.sleepwell.app;
import org.junit.Test;
import static org.junit.Assert.*;
/** Generated known acoustic paths exercise production DSP; no phone/physiological accuracy inference. */
public final class SonarDspTest {
 static short[] echo(long first,double delay,double echo,double audible){short[] pcm=new short[SonarConfig.CHIRP];for(int n=0;n<pcm.length;n++){double at=first+n,v=.5*SonarChirp.sample(at-8)+echo*SonarChirp.sample(at-delay)+audible*Math.sin(2*Math.PI*700*at/SonarConfig.RATE);pcm[n]=(short)Math.round(Math.max(-1,Math.min(1,v))*32767);}return pcm;}
 @Test public void gainRejectsInvalidAndPhaseIsContinuousAcrossChirpPeriods(){for(float gain:new float[]{Float.NaN,Float.POSITIVE_INFINITY,0,.101f})assertThrows(IllegalArgumentException.class,()->new SonarConfig(gain));assertEquals(SonarChirp.sample(0),SonarChirp.sample(1920),0);assertEquals(SonarChirp.sample(1.75),SonarChirp.sample(1921.75),1e-8);}
 @Test public void alignmentFindsKnownDirectPathInsteadOfUsingLoudness(){short[] data=new short[1920];for(int n=0;n<data.length;n++)data[n]=(short)(.6*32767*SonarChirp.sample(n-73));SonarAlignment.Match m=SonarAlignment.locate(data,0);assertEquals(73,m.lag,2);assertTrue(m.correlation>.65);assertEquals(0,SonarAlignment.locate(new short[1920],0).correlation,0);}
 @Test public void directLeakageAloneNeverQualifiesAsAnEcho(){SonarDsp dsp=new SonarDsp();for(int frame=0;frame<150;frame++){SonarFrame f=dsp.accept(echo(frame*1920L,240,0,0),frame*1920d);assertNull(f.movement);assertNotEquals(SonarFrame.Quality.VALID,f.quality);}}
 @Test public void stationaryDelayedEchoCannotPassRequiredMovementCheck(){SonarDsp dsp=new SonarDsp();boolean hasEcho=false;for(int frame=0;frame<150;frame++){SonarFrame f=dsp.accept(echo(frame*1920L,240,.16,0),frame*1920d);hasEcho|=f.quality==SonarFrame.Quality.NEEDS_MOVEMENT;assertNull(f.movement);}assertTrue("Actual off-direct echo was detected, but movement was not fabricated",hasEcho);}
 @Test public void movingEchoQualifiesAndLaterMeasuredStillnessIsZero(){SonarDsp dsp=new SonarDsp();int valid=0;SonarFrame last=null;for(int frame=0;frame<150;frame++){double delay=frame>=60&&frame<100?240+5*Math.sin(frame*.3):240;last=dsp.accept(echo(frame*1920L,delay,.16,.01),frame*1920d);if(last.quality==SonarFrame.Quality.VALID)valid++;}assertTrue("Real delayed moving reference passes the unchanged engineering policy",valid>=20);assertNotNull(last.movement);assertEquals("Stationary measured echo is zero after a valid movement check",0,last.movement,1e-6);}
 @Test public void audibleNoiseAndSilenceNeverBecomeValidMotion(){for(boolean noise:new boolean[]{false,true}){SonarDsp dsp=new SonarDsp();for(int frame=0;frame<80;frame++){short[] pcm=new short[1920];if(noise)for(int n=0;n<pcm.length;n++)pcm[n]=(short)(Math.sin(n*.5)*20000);assertNull(dsp.accept(pcm,frame*1920d).movement);}}}
 @Test public void clippingAndTimingDiscontinuityProduceMissingEvidence(){SonarDsp dsp=new SonarDsp();for(int frame=0;frame<3;frame++)dsp.accept(echo(frame*1920L,240,.16,0),frame*1920d);short[] clipped=new short[1920];java.util.Arrays.fill(clipped,Short.MAX_VALUE);SonarFrame f=dsp.accept(clipped,5760);assertEquals(SonarFrame.Quality.CLIPPED,f.quality);assertNull(f.movement);f=dsp.accept(echo(7680,240,.16,0),7687);assertEquals(SonarFrame.Quality.TIMING_LOST,f.quality);assertNull(f.movement);}
 @Test public void firstEchoAfterMissingSamplesDoesNotInventZeroMovement(){SonarDsp dsp=new SonarDsp();for(int frame=0;frame<110;frame++){double delay=frame>=60&&frame<100?240+5*Math.sin(frame*.3):240;dsp.accept(echo(frame*1920L,delay,.16,0),frame*1920d);}assertNull(dsp.accept(new short[1920],110*1920d).movement);SonarFrame recovered=dsp.accept(echo(111*1920L,240,.16,0),111*1920d);assertNull("A first frame after a gap has no measured delta",recovered.movement);assertEquals(SonarFrame.Quality.CALIBRATING,recovered.quality);assertEquals(0,dsp.accept(echo(112*1920L,240,.16,0),112*1920d).movement,1e-6);}
}
